/*
 * Proposal kit tokens. This is the ONLY file allowed to contain hex colors or px values
 * (scripts/check-tokens.mjs and the proposal-kit/tokens-only lint rule enforce it).
 * Every color pair used for text is checked for 4.5:1 contrast in src/styles/tokens.test.ts.
 */

:root {
  color-scheme: light;
  /* color */
  --pk-background: #f6f7f9;
  --pk-foreground: #14171f;
  --pk-card: #ffffff;
  --pk-card-foreground: #14171f;
  --pk-muted: #eef0f3;
  --pk-muted-foreground: #4a5260;
  --pk-border: #d3d8df;
  --pk-primary: #0d5c48;
  --pk-primary-foreground: #ffffff;
  --pk-secondary: #e3ebe8;
  --pk-secondary-foreground: #123d32;
  --pk-success: #dcf3e5;
  --pk-success-foreground: #12502d;
  --pk-estimate: #fbefd6;
  --pk-estimate-foreground: #6b4206;
  --pk-destructive: #b42318;
  --pk-ring: #1d5fd1;

  /* type */
  --pk-font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --pk-text-xs: 0.75rem;
  --pk-text-sm: 0.875rem;
  --pk-text-base: 1rem;
  --pk-text-lg: 1.125rem;
  --pk-text-xl: 1.25rem;
  --pk-text-2xl: 1.5rem;
  --pk-text-3xl: 1.875rem;

  /* spacing: Tailwind's p-4, gap-2 and so on are multiples of this */
  --pk-space-unit: 0.25rem;

  /* radius */
  --pk-radius-sm: 0.375rem;
  --pk-radius-md: 0.5rem;
  --pk-radius-lg: 0.75rem;
  --pk-radius-full: 9999px;

  /* border width */
  --pk-border-width: 1px;
  --pk-focus-width: 2px;
}

.dark {
  color-scheme: dark;
  --pk-background: #0e1116;
  --pk-foreground: #eceff3;
  --pk-card: #171b22;
  --pk-card-foreground: #eceff3;
  --pk-muted: #222831;
  --pk-muted-foreground: #a8b0bc;
  --pk-border: #353c48;
  --pk-primary: #6fd6b6;
  --pk-primary-foreground: #062a20;
  --pk-secondary: #1f3a33;
  --pk-secondary-foreground: #cfeee3;
  --pk-success: #133c26;
  --pk-success-foreground: #b4f0cc;
  --pk-estimate: #3d2c0c;
  --pk-estimate-foreground: #f6d9a3;
  --pk-destructive: #ff8a7f;
  --pk-ring: #7aa7ff;
}

/* Map the tokens into Tailwind. Tailwind's own palette is switched off, so bg-green-500 does not exist. */
@theme inline {
  --color-*: initial;
  --color-background: var(--pk-background);
  --color-foreground: var(--pk-foreground);
  --color-card: var(--pk-card);
  --color-card-foreground: var(--pk-card-foreground);
  --color-muted: var(--pk-muted);
  --color-muted-foreground: var(--pk-muted-foreground);
  --color-border: var(--pk-border);
  --color-input: var(--pk-border);
  --color-primary: var(--pk-primary);
  --color-primary-foreground: var(--pk-primary-foreground);
  --color-secondary: var(--pk-secondary);
  --color-secondary-foreground: var(--pk-secondary-foreground);
  --color-accent: var(--pk-secondary);
  --color-accent-foreground: var(--pk-secondary-foreground);
  --color-success: var(--pk-success);
  --color-success-foreground: var(--pk-success-foreground);
  --color-estimate: var(--pk-estimate);
  --color-estimate-foreground: var(--pk-estimate-foreground);
  --color-destructive: var(--pk-destructive);
  --color-ring: var(--pk-ring);
  --color-transparent: transparent;
  --color-current: currentColor;

  --font-sans: var(--pk-font-sans);
  --text-xs: var(--pk-text-xs);
  --text-sm: var(--pk-text-sm);
  --text-base: var(--pk-text-base);
  --text-lg: var(--pk-text-lg);
  --text-xl: var(--pk-text-xl);
  --text-2xl: var(--pk-text-2xl);
  --text-3xl: var(--pk-text-3xl);

  --spacing: var(--pk-space-unit);

  --radius-sm: var(--pk-radius-sm);
  --radius-md: var(--pk-radius-md);
  --radius-lg: var(--pk-radius-lg);
  --radius-xl: var(--pk-radius-lg);
  --radius-full: var(--pk-radius-full);
}

